import sys
import pandas as pd
import numpy as np
import json

# Read CSV
df = pd.read_csv(sys.argv[1])

facts = []

# Helper to convert numpy types to Python types
def to_python(val):
    if pd.isna(val):
        return None
    if isinstance(val, (np.integer, np.floating)):
        return float(val)
    return val

# 1. Top 5 entities by Revenue_TW
top_revenue = df.nlargest(5, 'Revenue_TW')
for idx, row in top_revenue.iterrows():
    if pd.notna(row['Revenue_TW']):
        facts.append({
            "entity": row['Entity'],
            "metric": "revenue",
            "period": "TW",
            "value": round(to_python(row['Revenue_TW']), 2),
            "formula": "Revenue_TW"
        })

# 2. Top 5 entities by Units_TW
top_units = df.nlargest(5, 'Units_TW')
for idx, row in top_units.iterrows():
    if pd.notna(row['Units_TW']):
        facts.append({
            "entity": row['Entity'],
            "metric": "units",
            "period": "TW",
            "value": to_python(row['Units_TW']),
            "formula": "Units_TW"
        })

# 3. Top 5 entities by Orders_TW
top_orders = df.nlargest(5, 'Orders_TW')
for idx, row in top_orders.iterrows():
    if pd.notna(row['Orders_TW']):
        facts.append({
            "entity": row['Entity'],
            "metric": "orders",
            "period": "TW",
            "value": to_python(row['Orders_TW']),
            "formula": "Orders_TW"
        })

# 4. Top 5 by WoW_Pct (biggest week-over-week movers)
wow_valid = df[df['WoW_Pct'].notna()].nlargest(5, 'WoW_Pct')
for idx, row in wow_valid.iterrows():
    facts.append({
        "entity": row['Entity'],
        "metric": "revenue",
        "period": "WoW",
        "value": round(to_python(row['WoW_Pct']), 1),
        "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
    })

# 5. Top 5 by YoY_Pct (biggest year-over-year movers)
yoy_valid = df[df['YoY_Pct'].notna()].nlargest(5, 'YoY_Pct')
for idx, row in yoy_valid.iterrows():
    facts.append({
        "entity": row['Entity'],
        "metric": "revenue",
        "period": "YoY",
        "value": round(to_python(row['YoY_Pct']), 1),
        "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
    })

# 6. TOTAL revenue TW, LW, LY
total_rev_tw = df['Revenue_TW'].sum()
total_rev_lw = df['Revenue_LW'].sum()
total_rev_ly = df['Revenue_LY'].sum()

if pd.notna(total_rev_tw):
    facts.append({
        "entity": "TOTAL",
        "metric": "revenue",
        "period": "TW",
        "value": round(to_python(total_rev_tw), 2),
        "formula": "SUM(Revenue_TW)"
    })

if pd.notna(total_rev_lw):
    facts.append({
        "entity": "TOTAL",
        "metric": "revenue",
        "period": "LW",
        "value": round(to_python(total_rev_lw), 2),
        "formula": "SUM(Revenue_LW)"
    })

if pd.notna(total_rev_ly):
    facts.append({
        "entity": "TOTAL",
        "metric": "revenue",
        "period": "LY",
        "value": round(to_python(total_rev_ly), 2),
        "formula": "SUM(Revenue_LY)"
    })

# 7. TOTAL WoW and YoY
if total_rev_lw > 0:
    total_wow = (total_rev_tw - total_rev_lw) / total_rev_lw * 100
    facts.append({
        "entity": "TOTAL",
        "metric": "revenue",
        "period": "WoW",
        "value": round(to_python(total_wow), 1),
        "formula": "(SUM(Revenue_TW) - SUM(Revenue_LW)) / SUM(Revenue_LW) * 100"
    })

if total_rev_ly > 0:
    total_yoy = (total_rev_tw - total_rev_ly) / total_rev_ly * 100
    facts.append({
        "entity": "TOTAL",
        "metric": "revenue",
        "period": "YoY",
        "value": round(to_python(total_yoy), 1),
        "formula": "(SUM(Revenue_TW) - SUM(Revenue_LY)) / SUM(Revenue_LY) * 100"
    })

# 8. TOTAL units and orders
total_units_tw = df['Units_TW'].sum()
total_orders_tw = df['Orders_TW'].sum()

if pd.notna(total_units_tw):
    facts.append({
        "entity": "TOTAL",
        "metric": "units",
        "period": "TW",
        "value": to_python(total_units_tw),
        "formula": "SUM(Units_TW)"
    })

if pd.notna(total_orders_tw):
    facts.append({
        "entity": "TOTAL",
        "metric": "orders",
        "period": "TW",
        "value": to_python(total_orders_tw),
        "formula": "SUM(Orders_TW)"
    })

# Limit to 25 facts
facts = facts[:25]

print(json.dumps(facts))
